#!/usr/bin/env node
// Read-only product review harness. All mutations are in a fresh owned /tmp directory.
// Usage: node security-runtime-repros.mjs /absolute/worktree [linked-hook|fifo|normal-exit|all]
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, chmodSync, existsSync, rmSync, symlinkSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join, delimiter, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';

const repo = resolve(process.argv[2] ?? '/tmp/loomake-quality-after-merge');
const selected = process.argv[3] ?? 'all';
const root = mkdtempSync(join(tmpdir(), 'loomake-security-repro-'));
const env = { ...process.env, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null' };
const output = { reviewType: 'isolated runtime reproduction, Linux/POSIX only', repository: repo, findings: [], inputHashes: {} };
const enginePids = new Set();
const sha = file => createHash('sha256').update(readFileSync(file)).digest('hex');
for (const file of ['src/guards.ts', 'src/engine.ts', 'dist/guards.js', 'dist/engine.js']) output.inputHashes['packages/runner/' + file] = sha(join(repo, 'packages/runner', file));
function run(command, args, cwd = root, options = {}) {
  const result = spawnSync(command, args, { cwd, env, encoding: 'utf8', timeout: 7000, ...options });
  if (result.error || result.status !== 0) throw new Error(JSON.stringify({ command, args, status: result.status, error: result.error?.message, stderr: result.stderr }));
  return result.stdout;
}
function git(cwd, args) { return run('git', args, cwd); }
function init(name) {
  const dir = join(root, name); mkdirSync(dir);
  git(dir, ['init', '-q']);
  git(dir, ['config', 'user.name', 'Security Review']);
  git(dir, ['config', 'user.email', 'review@example.invalid']);
  return dir;
}
function pidState(pid) {
  try { process.kill(pid, 0); } catch (error) { if (error.code === 'ESRCH') return 'missing'; throw error; }
  try { if (/\) Z /.test(readFileSync('/proc/' + pid + '/stat', 'utf8'))) return 'zombie'; } catch {}
  return 'running';
}
function collectOwnedPids() {
  const dir = join(root, 'normal-exit');
  for (const name of ['engine.pid', 'child.pid']) {
    const file = join(dir, name);
    if (!existsSync(file)) continue;
    const pid = Number(readFileSync(file, 'utf8'));
    if (Number.isSafeInteger(pid) && pid > 1) enginePids.add(pid);
  }
}
try {
  if (process.platform !== 'linux') throw new Error('This prepared reproduction harness is Linux-only.');
  const guardsUrl = pathToFileURL(join(repo, 'packages/runner/dist/guards.js')).href;
  if (selected === 'all' || selected === 'linked-hook') {
    const { gitInternals, findInternalsChange, findViolations } = await import(guardsUrl);
    const dir = init('linked-hook'); mkdirSync(join(dir, 'scripts'));
    const target = join(dir, 'scripts/hook.sh'); const marker = join(dir, 'hook-executed');
    writeFileSync(target, '#!/bin/sh\nexit 0\n'); chmodSync(target, 0o755);
    git(dir, ['add', '-A']); git(dir, ['commit', '-q', '-m', 'initial']);
    symlinkSync('../../scripts/hook.sh', join(dir, '.git/hooks/pre-commit'));
    const before = gitInternals(dir, env);
    writeFileSync(target, '#!/bin/sh\nprintf harmless > "' + marker + '"\n');
    const after = gitInternals(dir, env);
    const changed = findInternalsChange(dir, env, before);
    const violations = findViolations(dir, env);
    git(dir, ['add', 'scripts/hook.sh']);
    git(dir, ['commit', '-q', '-m', 'simulated engine edit']);
    output.findings.push({
      id: 'SEC-STATIC-01', classification: 'design_trust_policy_gap_not_REQ_204_implementation_violation',
      beforeDigest: before.digest, afterDigest: after.digest, internalsChange: changed ?? null,
      violations: violations.findings, markerCreatedByCommit: existsSync(marker),
      reproduced: before.digest === after.digest && changed === undefined && violations.findings.length === 0 && existsSync(marker),
      policy: 'REQ-204 explicitly requires links inside the hook directory be compared by link text without following them.'
    });
  }
  if (selected === 'all' || selected === 'fifo') {
    const dir = init('fifo');
    writeFileSync(join(dir, '.git/hooks/review-pipe'), 'regular entry');
    const childSource = [
      'const { gitInternals } = await import(' + JSON.stringify(guardsUrl) + ');',
      'process.stdout.write("snapshot-started\\n");',
      'gitInternals(' + JSON.stringify(dir) + ', process.env);',
      'process.stdout.write("snapshot-returned\\n");'
    ].join('\n');
    const baseline = spawnSync(process.execPath, ['--input-type=module', '-e', childSource], {
      cwd: dir, env, encoding: 'utf8', timeout: 1500, killSignal: 'SIGKILL', maxBuffer: 1024 * 1024
    });
    rmSync(join(dir, '.git/hooks/review-pipe'));
    run('mkfifo', [join(dir, '.git/hooks/review-pipe')]);
    const started = Date.now();
    const result = spawnSync(process.execPath, ['--input-type=module', '-e', childSource], {
      cwd: dir, env, encoding: 'utf8', timeout: 1500, killSignal: 'SIGKILL', maxBuffer: 1024 * 1024
    });
    output.findings.push({
      id: 'SEC-STATIC-02', regularFileControl: { status: baseline.status, stdout: baseline.stdout, stderr: baseline.stderr }, elapsedMs: Date.now() - started, status: result.status, signal: result.signal,
      errorCode: result.error?.code ?? null, stdout: result.stdout, stderr: result.stderr,
      reproduced: baseline.status === 0 && baseline.stdout.includes('snapshot-returned') && result.error?.code === 'ETIMEDOUT' && result.stdout.includes('snapshot-started') && !result.stdout.includes('snapshot-returned')
    });
  }
  if (selected === 'all' || selected === 'normal-exit') {
    const dir = join(root, 'normal-exit'); mkdirSync(dir);
    const entry = join(dir, 'claude');
    const childSource = [
      "const fs = require('node:fs');",
      "fs.writeFileSync('child.pid', String(process.pid));",
      "fs.writeFileSync('child.ready', 'ready');",
      "setTimeout(() => { fs.writeFileSync('delayed-marker', 'harmless'); }, 500);",
      "setTimeout(() => process.exit(0), 1200);"
    ].join('\n');
    const engineSource = [
      '#!/usr/bin/env node',
      "const fs = require('node:fs');",
      "fs.writeFileSync('engine.pid', String(process.pid));",
      "require('node:child_process').spawn(process.execPath, ['-e', " + JSON.stringify(childSource) + "], { stdio: 'ignore', detached: false });",
      "const poll = setInterval(() => { if (fs.existsSync('child.ready')) process.exit(0); }, 10);"
    ].join('\n');
    writeFileSync(entry, engineSource); chmodSync(entry, 0o755);
    const workerSource = [
      'const { runClaude } = await import(' + JSON.stringify(pathToFileURL(join(repo, 'packages/runner/dist/engine.js')).href) + ');',
      "const fs = await import('node:fs');",
      'const result = await runClaude({ cwd: ' + JSON.stringify(dir) + ", env: process.env, prompt: 'review', commands: [], skipPermissions: false, timeoutMs: 3000 });",
      "const pid = Number(fs.readFileSync('child.pid', 'utf8'));",
      "let state; try { process.kill(pid, 0); state = 'running'; } catch { state = 'missing'; }",
      "try { if (fs.readFileSync('/proc/' + pid + '/stat', 'utf8').split(') ')[1]?.startsWith('Z ')) state = 'zombie'; } catch {}",
      "const markerAtReturn = fs.existsSync('delayed-marker');",
      'await new Promise(resolve => setTimeout(resolve, 650));',
      "console.log(JSON.stringify({ result, childPid: pid, stateAtReturn: state, markerAtReturn, markerAfterReturn: fs.existsSync('delayed-marker') }));"
    ].join('\n');
    const workerEnv = { ...env, PATH: dir + delimiter + (env.PATH ?? '') };
    const worker = spawnSync(process.execPath, ['--input-type=module', '-e', workerSource], {
      cwd: dir, env: workerEnv, encoding: 'utf8', timeout: 5000, killSignal: 'SIGKILL', maxBuffer: 1024 * 1024
    });
    collectOwnedPids();
    if (worker.error || worker.status !== 0) throw new Error(JSON.stringify({ stage: 'normal-exit', status: worker.status, error: worker.error?.message, stdout: worker.stdout, stderr: worker.stderr }));
    const observed = JSON.parse(worker.stdout.trim());
    output.findings.push({ id: 'SEC-STATIC-03', ...observed, reproduced: observed.result.exitCode === 0 && !observed.result.timedOut && observed.stateAtReturn === 'running' && !observed.markerAtReturn && observed.markerAfterReturn });
  }
} catch (error) {
  output.error = String(error.stack ?? error); process.exitCode = 1;
} finally {
  collectOwnedPids();
  for (const pid of enginePids) if (pidState(pid) === 'running') {
    try { process.kill(pid, 'SIGKILL'); } catch (error) { if (error.code !== 'ESRCH') output.cleanupError = String(error); }
  }
  output.cleanup = { directory: root, removed: false, recordedOwnedPids: [...enginePids] };
  rmSync(root, { recursive: true, force: true }); output.cleanup.removed = !existsSync(root);
  console.log(JSON.stringify(output, null, 2));
}
